package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.util.StringUtils;

/**
 * Normalizes a newly created owner's city name. The city is title-cased (each
 * whitespace-separated word gets a leading capital and a lower-cased remainder,
 * e.g. {@code "new york"} becomes {@code "New York"}). However, if an owner already
 * exists in that city - matched case-insensitively - the existing owner's exact
 * spelling of the city name is reused instead, so a city is spelled consistently
 * across all owners regardless of how later creators capitalize it.
 */
public class NormalizeOwnerCity {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String city = owner.getCity();
        if (!StringUtils.hasText(city)) {
            return;
        }
        for (Owner existing : ownerRepository.findAll()) {
            String existingCity = existing.getCity();
            if (existingCity != null && existingCity.equalsIgnoreCase(city)) {
                owner.setCity(existingCity);
                return;
            }
        }
        owner.setCity(titleCase(city));
    }

    /**
     * Title-cases each whitespace-separated word: leading character upper-cased,
     * the remainder lower-cased. Preserves the original whitespace between words.
     */
    private static String titleCase(String value) {
        StringBuilder result = new StringBuilder(value.length());
        boolean startOfWord = true;
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (Character.isWhitespace(c)) {
                startOfWord = true;
                result.append(c);
            }
            else if (startOfWord) {
                result.append(Character.toUpperCase(c));
                startOfWord = false;
            }
            else {
                result.append(Character.toLowerCase(c));
            }
        }
        return result.toString();
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Objects;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.OwnerConflictException;
import org.springframework.util.StringUtils;

/**
 * Rejects creating an owner that clashes with an existing one - with a 409 via
 * {@link OwnerConflictException}. An owner clashes when its telephone number is
 * already used by another owner, or (when an email address is provided) when that
 * email is already used by another owner.
 *
 * <p>Email duplicate detection is insensitive to letter case and to surrounding or
 * repeated whitespace: values are {@link #normalize(String) normalized} before
 * comparison, so {@code "  john   smith "} and {@code "John Smith"} are treated as
 * the same value. Telephone duplicate detection compares
 * {@link OwnerTelephones#digitsOnly(String) digits only}, so {@code "(613) 555-0100"}
 * and {@code "6135550100"} are treated as the same number.
 */
public class EnsureOwnerUnique {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws OwnerConflictException {
        String telephone = OwnerTelephones.digitsOnly(owner.getTelephone());
        String email = normalize(owner.getEmail());
        boolean hasEmail = StringUtils.hasText(email);
        for (Owner existing : ownerRepository.findAll()) {
            if (Objects.equals(OwnerTelephones.digitsOnly(existing.getTelephone()), telephone)) {
                throw new OwnerConflictException(
                        "An owner with the same telephone already exists");
            }
            if (hasEmail && Objects.equals(normalize(existing.getEmail()), email)) {
                throw new OwnerConflictException(
                        "An owner with the same email already exists");
            }
        }
    }

    /**
     * Normalizes a value for case- and whitespace-insensitive comparison: trims
     * surrounding whitespace, collapses each run of internal whitespace to a single
     * space, and lower-cases the result. {@code null} maps to {@code null}.
     */
    private static String normalize(String value) {
        if (value == null) {
            return null;
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}

